    "title": "UAE Confirmation of Payee API",
    "description": "## UAE Open Finance Confirmation of Payee API Specification",
    "version": "v2.1-errata2"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/confirmation-of-payee/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/confirmation-of-payee/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/confirmation-of-payee/v2.1"
    }
  ],
  "source_path": "/discovery",
  "operations": {
    "post": {
      "operationId": "ConfirmationOfPayeeDiscovery_signedDiscoveryRequest",
      "summary": "Discover the LFI that will confirm the payee attributes",
      "description": "Before a Confirmation of Payee (CoP) operation takes place the TPP will need to resolve the LFI that will service the account properties request. This requirement is based on the separation of concerns implemented in the OFP, which ensures that the APIs for a given LFI are always physically separated.\n\nThe TPP will call this endpoint with the Creditor Account IBAN, which will be used to resolve the correct URL with which to make the CoP operation.",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        }
      ],
      "responses": {
        "200": {
          "description": "The request has succeeded.",
          "headers": {
            "x-fapi-interaction-id": {
              "required": false,
              "description": "An RFC4122 UID used as a correlation ID.",
              "schema": {
                "type": "string"
              }
            }
          },
          "content": {
            "application/jwt": {
              "schema": {
                "$ref": "#/components/schemas/DiscoverConfirmationSourceResponseBodySigned"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "tags": [
        "Discovery Operations"
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/jwt": {
            "schema": {
              "$ref": "#/components/schemas/DiscoverConfirmationSourceRequestBodySigned"
            }
          }
        }
      },
      "security": [
        {
          "TPPOAuth2Security": [
            "confirmation-of-payee"
          ]
        }
      ]
    }
  }
}

